465	/// Starts a real local `pypiserver` on an ephemeral loopback port with
466	/// authentication fully disabled (`-a . -P .`, its own documented way to
467	/// allow anonymous browsing and uploads) and `--disable-fallback`, so a
468	/// lookup for an unknown project 404s instead of proxying to real PyPI.
469	///
470	/// `--server gunicorn`: pypiserver's default `auto` backend selection falls
471	/// through to `wsgiref` when nothing else is installed, and `wsgiref`
472	/// (like `paste` and gevent's `pywsgi`, also measured) resolves the bind
473	/// address via `socket.getfqdn()` before it starts listening -- a reverse
474	/// DNS lookup that measured 12-35s on a real machine exhibiting the same
475	/// symptom as the CI macOS runner, against sub-second on Linux. `gunicorn`
476	/// has no such call anywhere in its source (grepped) and measured
477	/// consistently under 1s across repeated runs here; it forks a worker and
478	/// terminates both master and worker cleanly on the one SIGTERM `ServerGuard`
479	/// sends the master PID.
480	fn start_pypiserver(external: &Path) -> (ServerGuard, u16) {
481	    let packages_dir = external.join("pypiserver-packages");
482	    fs::create_dir_all(&packages_dir).unwrap();
483	    let port = free_loopback_port();
484	    let mut command = Command::new("pypi-server");
