fn cargo_release_fixture() -> (tempfile::TempDir, String) {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    git(root, &["remote", "add", "origin", CARGO_ORIGIN]);
    fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"crates/probe\"]\nresolver = \"2\"\n").unwrap();
    fs::create_dir_all(root.join("crates/probe/src")).unwrap();
    fs::write(
        root.join("crates/probe/Cargo.toml"),
        format!(
            "[package]\nname = \"{CARGO_PACKAGE}\"\nversion = \"0.1.0\"\nedition = \"2021\"\n\
             description = \"verify-real probe\"\nlicense = \"MIT\"\n"
        ),
    )
    .unwrap();
    fs::write(root.join("crates/probe/src/lib.rs"), "pub fn probe() {}\n").unwrap();
    fs::write(root.join(".gitignore"), "/target/\n").unwrap();
    let lock = std::process::Command::new("cargo")
        .args(["generate-lockfile", "--offline"])
        .current_dir(root)
        .output()
        .expect("cargo must be runnable");
    assert!(lock.status.success(), "lockfile failed: {}", String::from_utf8_lossy(&lock.stderr));
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "initial workspace"]);

    let init = callisto(root, &["init", "--yes", "--versioning", "independent"]);
    assert!(init.status.success(), "init failed: {}", stderr_of(&init));
    let config_path = root.join("callisto.toml");
    let mut config = fs::read_to_string(&config_path).unwrap();
    config.push_str(&format!("\n[[package]]\nmatch = \"cargo/{CARGO_PACKAGE}\"\npublish-to = [\"crates-io\"]\n"));
    fs::write(&config_path, config).unwrap();
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "configure callisto"]);

    let add = callisto(
        root,
        &["add", "--package", &format!("cargo/{CARGO_PACKAGE}:minor"), "--summary", "Ship the verify-real probe"],
    );
    assert!(add.status.success(), "add failed: {}", stderr_of(&add));
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "add release changeset"]);

    let version = callisto(root, &["version", "--no-refresh-lockfiles", "--emit-decision", DECISION_PATH]);
    assert!(version.status.success(), "version failed: {}", stderr_of(&version));
    git(root, &["add", "-A"]);
    git(root, &["commit", "-m", "release the probe 0.2.0"]);
    let release_commit = git(root, &["rev-parse", "HEAD"]);
    git(root, &["checkout", "--detach", &release_commit]);
    (dir, release_commit)
}

#[test]
#[ignore = "needs local registries; run via `just verify-real`"]
fn a_crate_published_by_an_earlier_run_is_adopted_by_the_rerun() {
    let external = tempfile::tempdir().unwrap();
    let tls = Tls::generate(external.path());
    let fixture = cargo_release_fixture();
    let registry_root = external.path().join("cargo-registry");
    let (_registry, port) = start_cargo_http_registry(external.path(), &registry_root);
    // Cargo's own routing, outside the worktree: crates.io is replaced by the local registry.
    let cargo_home = external.path().join("cargo-home");
    fs::create_dir_all(&cargo_home).unwrap();
    fs::write(
        cargo_home.join("config.toml"),
        format!(
            "[source.crates-io]\nreplace-with = \"local-verify\"\n\n[source.local-verify]\nregistry = \"http://127.0.0.1:{port}/git\"\n\n\
             [net]\ngit-fetch-with-cli = true\n"
        ),
    )
    .unwrap();
    let mut release = Release::new(fixture, external, tls, CARGO_ORIGIN, &format!("{CARGO_PACKAGE}@0.2.0"));
    release.rig.set("CARGO_HOME", cargo_home.to_str().unwrap());

    // The earlier run published the crate, then died before the tag and the receipt.
    let published = std::process::Command::new("cargo")
        .args(["publish", "--locked", "--registry", "crates-io"])
        .current_dir(release.root())
        .env("CARGO_HOME", &cargo_home)
        .env("CARGO_REGISTRY_TOKEN", "callisto-verify-token")
        .output()
        .expect("cargo must be runnable");
    assert!(published.status.success(), "seeding publish failed: {}", String::from_utf8_lossy(&published.stderr));

    let output = release.execute();
    release.assert_completed(&output);
    assert!(
        stderr_of(&output).contains("already published"),
        "the rerun must adopt the crate instead of publishing it again:\n{}",
        stderr_of(&output)
    );
    assert!(release.remote_has_tag(&format!("{CARGO_PACKAGE}@0.2.0")), "the tag must reach the remote");
}

